import time
import functools
from typing import Type


def retry(max_retries: int = 3, delay: float = 0, exceptions: tuple[Type[Exception], ...] = (Exception,)):
    """Decorator that retries a function up to max_retries times on exception.

    Args:
        max_retries: Maximum number of retry attempts (default 3).
        delay: Seconds to wait between retries (default 0).
        exceptions: Tuple of exception types to catch (default catches all).
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    last_exc = exc
                    if attempt < max_retries:
                        if delay > 0:
                            time.sleep(delay)
            raise last_exc
        return wrapper
    return decorator


# ── Usage examples ──────────────────────────────────────────────────

@retry(max_retries=3, delay=0.5)
def unreliable_api_call():
    """Simulates a flaky network call."""
    import random
    if random.random() < 0.7:
        raise ConnectionError("Network timeout")
    return {"status": "ok"}


@retry(max_retries=5, exceptions=(ValueError, KeyError))
def parse_data(raw: dict):
    """Retries only on ValueError or KeyError."""
    if "data" not in raw:
        raise KeyError("Missing 'data' key")
    return raw["data"]


# ── Tests ───────────────────────────────────────────────────────────

def test_succeeds_first_try():
    call_count = 0

    @retry(max_retries=3)
    def succeed():
        nonlocal call_count
        call_count += 1
        return "ok"

    assert succeed() == "ok"
    assert call_count == 1


def test_succeeds_after_retries():
    call_count = 0

    @retry(max_retries=3)
    def flaky():
        nonlocal call_count
        call_count += 1
        if call_count < 3:
            raise ValueError("not yet")
        return "done"

    assert flaky() == "done"
    assert call_count == 3


def test_raises_after_max_retries():
    call_count = 0

    @retry(max_retries=2)
    def always_fail():
        nonlocal call_count
        call_count += 1
        raise RuntimeError("boom")

    try:
        always_fail()
        assert False, "Should have raised"
    except RuntimeError as exc:
        assert str(exc) == "boom"
    assert call_count == 3  # 1 initial + 2 retries


def test_only_catches_specified_exceptions():
    call_count = 0

    @retry(max_retries=3, exceptions=(ValueError,))
    def wrong_exception():
        nonlocal call_count
        call_count += 1
        raise TypeError("wrong type")

    try:
        wrong_exception()
        assert False, "Should have raised"
    except TypeError:
        pass
    assert call_count == 1  # no retry for TypeError


def test_preserves_function_metadata():
    @retry(max_retries=2)
    def documented():
        """This is the docstring."""
        return True

    assert documented.__name__ == "documented"
    assert documented.__doc__ == "This is the docstring."


def test_passes_args_and_kwargs():
    @retry(max_retries=2)
    def add(a, b, extra=0):
        return a + b + extra

    assert add(1, 2) == 3
    assert add(1, 2, extra=10) == 13


if __name__ == "__main__":
    test_succeeds_first_try()
    test_succeeds_after_retries()
    test_raises_after_max_retries()
    test_only_catches_specified_exceptions()
    test_preserves_function_metadata()
    test_passes_args_and_kwargs()
    print("All tests passed.")
